#[capability(
    module = "ebay",
    id = "update-offer",
    display_name = r##"Update Offer"##,
    description = r##"This call updates an existing offer. An existing offer may be in published state (active eBay listing), or in an unpublished state and yet to be published with the publishOffer call. The unique identifier (offerId) for the offer to update is passed in at the end of the call URI.

The updateOffer call does a complete replacement of the existing offer object, so all fields that make up the current offer object are required, regardless of whether their values changed.

Important!Publish offer note: Fields may be optional or conditionally required when calling this method, but become required when publishing the offer to create an active listing. For this method, see Offer fields for a list of fields required to publish an offer.

Other information that is required before an unpublished offer can be published or before a published offer can be revised include:

- Inventory location
- Offer price
- Available quantity
- eBay listing category
- Referenced listing policy profiles to set payment, return, and fulfillment values/settings

Note: Though the includeCatalogProductDetails parameter is not required to be submitted in the request, the parameter defaults to `true` if omitted from both the updateOffer and the createOffer calls. If a value is specified in the updateOffer call, this value will be used.
Note: In addition to the `authorization` header, which is required for all Inventory API calls, this call also requires the `Content-Type` and `Content-Language` headers. See the HTTP request headers for more information.
Note: Each listing can be revised up to 250 times in one calendar day. If this revision threshold is reached, the seller will be blocked from revising the item until the next calendar day.

For published offers, the listingDescription field is also required to update the offer/eBay listing. For unpublished offers, this field is not necessarily required unless it is already set for the unpublished offer."##,
    side_effects = true
)]
pub async fn update_offer(input: UpdateOfferInput) -> Result<OfferResponse, AgentError> {
    let connection = kit::require_connection(&input._connection, "EBAY")?;
    input.request()?.send(connection, "EBAY").await
}

impl UpdateOfferInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/sell/inventory/v1/offer/{offerId}",
            offerId = kit::encode_path(&self.offer_id)
        );
        let request =
            kit::Request::new("PUT", path).header("Content-Language", &self.content_language);
        request.json_body(
            kit::Body::new()
                .field_opt("availableQuantity", &self.available_quantity)
                .field_opt("categoryId", &self.category_id)
                .field_opt("charity", &self.charity)
                .field_opt(
                    "extendedProducerResponsibility",
                    &self.extended_producer_responsibility,
                )
                .field_opt("hideBuyerDetails", &self.hide_buyer_details)
                .field_opt(
                    "includeCatalogProductDetails",
                    &self.include_catalog_product_details,
                )
                .field_opt("listingDescription", &self.listing_description)
                .field_opt("listingDuration", &self.listing_duration)
                .field_opt("listingPolicies", &self.listing_policies)
                .field_opt("listingStartDate", &self.listing_start_date)
                .field_opt("lotSize", &self.lot_size)
                .field_opt("merchantLocationKey", &self.merchant_location_key)
                .field_opt("pricingSummary", &self.pricing_summary)
                .field_opt("quantityLimitPerBuyer", &self.quantity_limit_per_buyer)
                .field_opt("regulatory", &self.regulatory)
                .field_opt("secondaryCategoryId", &self.secondary_category_id)
                .field_opt("storeCategoryNames", &self.store_category_names)
                .field_opt("tax", &self.tax),
            "EBAY",
        )
    }
}

