#[derive(Debug, Serialize, Deserialize, CapabilityInput)]
#[capability_input(display_name = r##"Create Shipping Fulfillment"##)]
pub struct CreateShippingFulfillmentInput {
    #[field(skip)]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub _connection: Option<RawConnection>,
    #[field(
        display_name = r##"Order ID"##,
        description = r##"This path parameter is used to specify the unique identifier of the order associated with the shipping fulfillment being created.

Use the getOrders method to retrieve order IDs."##
    )]
    #[serde(rename = "orderId")]
    pub order_id: String,
    #[field(
        display_name = r##"Line Items"##,
        description = r##"This array contains a list of or more line items and the quantity that will be shipped in the same package."##
    )]
    #[serde(rename = "lineItems", default, skip_serializing_if = "Option::is_none")]
    pub line_items: Option<Vec<LineItemReference>>,
    #[field(
        display_name = r##"Shipped Date"##,
        description = r##"This is the actual date and time that the fulfillment package was shipped. This timestamp is in ISO 8601 format, which uses the 24-hour Universal Coordinated Time (UTC) clock. The seller should use the actual date/time that the package was shipped, but if this field is omitted, it will default to the current date/time.

Format: `[YYYY]-[MM]-[DD]T[hh]:[mm]:[ss].[sss]Z`
Example: `2015-08-04T19:09:02.768Z`

Default: The current date and time."##
    )]
    #[serde(
        rename = "shippedDate",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub shipped_date: Option<String>,
    #[field(
        display_name = r##"Shipping Carrier Code"##,
        description = r##"The unique identifier of the shipping carrier being used to ship the line item(s). Technically, the shippingCarrierCode and trackingNumber fields are optional, but generally these fields will be provided if the shipping carrier and tracking number are known.

Note: Use the Trading API's GeteBayDetails call to retrieve the latest shipping carrier enumeration values. When making the GeteBayDetails call, include the DetailName field in the request payload and set its value to `ShippingCarrierDetails`. Each valid shipping carrier enumeration value is returned in a ShippingCarrierDetails.ShippingCarrier field in the response payload."##
    )]
    #[serde(
        rename = "shippingCarrierCode",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub shipping_carrier_code: Option<String>,
    #[field(
        display_name = r##"Tracking Number"##,
        description = r##"The tracking number provided by the shipping carrier for this fulfillment. The seller should be careful that this tracking number is accurate since the buyer will use this tracking number to track shipment, and eBay has no way to verify the accuracy of this number.

This field and the shippingCarrierCode field are mutually dependent. If you include one, you must also include the other.

Note: If you include trackingNumber (and shippingCarrierCode) in the request, the resulting fulfillment's ID (returned in the HTTP location response header) is the tracking number. If you do not include shipment tracking information, the resulting fulfillment ID will default to an arbitrary number such as `999`.
Note: Only alphanumeric characters are supported for shipment tracking numbers. Spaces, hyphens, and all other special characters are not supported. Do not include a space in the tracking number even if a space appears in the tracking number on the shipping label."##
    )]
    #[serde(
        rename = "trackingNumber",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub tracking_number: Option<String>,
}

#[capability(
    module = "ebay",
    id = "create-shipping-fulfillment",
    display_name = r##"Create Shipping Fulfillment"##,
    description = r##"When you group an order's line items into one or more packages, each package requires a corresponding plan for handling, addressing, and shipping; this is a shipping fulfillment. For each package, execute this call once to generate a shipping fulfillment associated with that package.

Note: A single line item in an order can consist of multiple units of a purchased item, and one unit can consist of multiple parts or components. Although these components might be provided by the manufacturer in separate packaging, the seller must include all components of a given line item in the same package.

Before using this call for a given package, you must determine which line items are in the package. If the package has been shipped, you should provide the date of shipment in the request. If not provided, it will default to the current date and time."##,
    side_effects = true
)]
pub async fn create_shipping_fulfillment(
    input: CreateShippingFulfillmentInput,
) -> Result<Value, AgentError> {
    let connection = kit::require_connection(&input._connection, "EBAY")?;
    input.request()?.send(connection, "EBAY").await
}

impl CreateShippingFulfillmentInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = format!(
            "/sell/fulfillment/v1/order/{orderId}/shipping_fulfillment",
            orderId = kit::encode_path(&self.order_id)
        );
        let request = kit::Request::new("POST", path);
        request.json_body(
            kit::Body::new()
                .field_opt("lineItems", &self.line_items)
                .field_opt("shippedDate", &self.shipped_date)
                .field_opt("shippingCarrierCode", &self.shipping_carrier_code)
                .field_opt("trackingNumber", &self.tracking_number),
            "EBAY",
        )
    }
}

